import test from 'node:test';
import assert from 'node:assert/strict';
import {parseProcessRows, sampleOwnedProcesses} from './process_rss.mjs';

const ps = ' 101  1  2048 Thu Sep 17 00:01:02 2026 /usr/bin/browser --flag with spaces\n 202  1  0 Thu Sep 17 00:01:03 2026 /usr/bin/server --serve\n';
test('parses strict ps rows and preserves command/date identity', () => { assert.deepEqual(parseProcessRows(ps), [{pid:101,ppid:1,rss_kib:2048,start_identity:'Thu Sep 17 00:01:02 2026',command:'/usr/bin/browser --flag with spaces'},{pid:202,ppid:1,rss_kib:0,start_identity:'Thu Sep 17 00:01:03 2026',command:'/usr/bin/server --serve'}]); });
for (const raw of [' 1 0 2 Thu Sep 17 00:01:02 2026 x\n 1 0 2 Thu Sep 17 00:01:02 2026 y\n','x\n',' 1 0 -2 Thu Sep 17 00:01:02 2026 x\n',' 0 0 2 Thu Sep 17 00:01:02 2026 x\n']) test('rejects malformed or duplicate ps rows', () => { assert.throws(() => parseProcessRows(raw)); });
for (const raw of [' 1 0 2 Funday Sep 17 00:01:02 2026 x\n',' 1 0 2 Thu Foo 17 00:01:02 2026 x\n',' 1 0 2 Thu Sep 32 00:01:02 2026 x\n',' 1 0 2 Thu Sep 17 24:01:02 2026 x\n']) test('rejects non-C-locale dates', () => { assert.throws(() => parseProcessRows(raw)); });
test('samples exact owner set with injectable ps and retains raw output', async () => { let clock=100; const result=await sampleOwnedProcesses({browserPid:101,serverPid:202,now:()=>++clock,send:async method=>{assert.equal(method,'SystemInfo.getProcessInfo');return {processInfo:[{type:'browser',id:101},{type:'renderer',id:303}]}},readPS:async pids=>{assert.deepEqual(pids,[101,303,202]);return ps;}}); assert.deepEqual(result.rows.map(row=>row.pid),[101,202]); assert.equal(result.raw_ps,ps); assert.equal(result.errors.length,1); assert.match(result.errors[0].message,/missing owned PID 303/); });
test('records browser query and ps failures without fabricating rows', async () => { const query=await sampleOwnedProcesses({browserPid:101,serverPid:202,send:async()=>{throw new Error('cdp down')},readPS:async()=>{throw new Error('must not run')}}); assert.equal(query.rows.length,0); assert.match(query.errors[0].message,/cdp down/); const psFailure=await sampleOwnedProcesses({browserPid:101,serverPid:202,send:async()=>({processInfo:[{type:'browser',id:101}]}),readPS:async()=>{throw new Error('ps down')}}); assert.equal(psFailure.rows.length,0); assert.match(psFailure.errors[0].message,/ps down/); });
test('rejects unknown browser owner', async () => { const result=await sampleOwnedProcesses({browserPid:999,serverPid:202,send:async()=>({processInfo:[{type:'browser',id:101}]}),readPS:async()=>ps}); assert.equal(result.rows.length,0); assert.match(result.errors[0].message,/does not match/); });
test('rejects string IDs, server/browser overlap, and extra ps rows', async () => { const stringID=await sampleOwnedProcesses({browserPid:101,serverPid:202,send:async()=>({processInfo:[{type:'browser',id:'101'}]}),readPS:async()=>ps}); assert.match(stringID.errors[0].message,/non-numeric/); const overlap=await sampleOwnedProcesses({browserPid:101,serverPid:202,send:async()=>({processInfo:[{type:'browser',id:202},{type:'renderer',id:101}]}),readPS:async()=>ps}); assert.match(overlap.errors[0].message,/server PID/); const extra=await sampleOwnedProcesses({browserPid:101,serverPid:202,send:async()=>({processInfo:[{type:'browser',id:101}]}),readPS:async()=>ps+' 303  1  1 Thu Sep 17 00:01:04 2026 /extra'}); assert.match(extra.errors[0].message,/unrequested PID 303/); });
